add("D02", G + "lib.rs", 'b"Tacenta Group Application v1"', 'b"Tacenta Group Application v2"', "application-context domain string changed")
add("D03", G + "payload.rs", 'b"Tacenta Group Payload v1"', 'b"Tacenta Group Payload v2"', "group payload domain string changed")
add("D04", G + "invitation.rs", 'b"Tacenta Group Invitation Bootstrap v1"', 'b"Tacenta Group Invitation Bootstrap v2"', "bootstrap domain string changed")
add("D05", G + "invitation.rs", 'b"Tacenta Group Invitation Acceptance v1"', 'b"Tacenta Group Invitation Revocation v1"', "acceptance uses the revocation domain string")
add("D06", G + "invitation.rs", 'b"Tacenta Group Invitation Revocation v1"', 'b"Tacenta Group Invitation Acceptance v1"', "revocation uses the acceptance domain string")
add("D07", G + "send.rs", 'b"Tacenta Group Logical Send v1"', 'b"Tacenta Group Logical Send v2"', "logical-send intent domain string changed")
add("D08", G + "lib.rs", "fn take_exact(input: &mut &[u8], expected: &[u8]) -> Result<(), Error> {\n    if take(expected.len(), input)?.as_slice() == expected {", "fn take_exact(input: &mut &[u8], expected: &[u8]) -> Result<(), Error> {\n    if take(expected.len(), input)?.len() == expected.len() {", "roster and context decoders no longer compare the domain string, only its length")

